{"code": "import re, math
PDF='2022_281692_KUUSANMAKI_SUPPL.pdf'

def cluster_xs(vals, tol=8.0):
    xs=sorted(vals); groups=[]
    for x in xs:
        if not groups or abs(x-groups[-1][-1])>tol: groups.append([x])
        else: groups[-1].append(x)
    centers=[sum(g)/len(g) for g in groups]
    return centers, lambda x: min(range(len(centers)), key=lambda i: abs(x-centers[i]))

def auc_higher(scores, truth):
    pairs=sorted(zip(scores,truth), key=lambda z:z[0]); ranks={}; i=0
    while i<len(pairs):
        j=i+1
        while j<len(pairs) and pairs[j][0]==pairs[i][0]: j+=1
        avg=(i+1+j)/2
        for k in range(i,j): ranks[k]=avg
        i=j
    pos=sum(truth); neg=len(truth)-pos
    return (sum(ranks[k] for k,(_,y) in enumerate(pairs) if y==1)-pos*(pos+1)/2)/(pos*neg)
def truth_value(t):
    t=t.strip().upper()
    if t in ('CR','CRI','MLFS','CR/CRI','CR / CRI') or 'CR/CRI' in t: return 1
    if t in ('RD','PD') or 'RESISTANT DISEASE' in t or 'REFRACTORY DISEASE' in t: return 0
    return None

candidates=[]
for sh in list(tables[PDF].keys()):
    obj=tables[PDF][sh]; geo=obj.get('geometry',[])
    words=[]
    for r,gr in enumerate(geo):
        cs=sorted(gr.get('cells',[]), key=lambda c:c.get('x0',0))
        for ci,c in enumerate(cs):
            text=str(c.get('text','')).strip(); x=c.get('x0')
            if text and x is not None:
                words.append({'r':r,'x':float(x),'text':text,'ref':f'{PDF}/{sh}/R{r+1}C{ci+1}'})
    if not words: continue
    centers,nearest=cluster_xs([w['x'] for w in words])
    for w in words: w['col']=nearest(w['x'])
    headers=[' '.join(w['text'] for w in words if w['col']==col and w['r']<14).lower() for col in range(len(centers))]
    label_counts=[0]*len(centers)
    for w in words:
        if truth_value(w['text']) is not None: label_counts[w['col']]+=1
    for sc,h in enumerate(headers):
        fc_cm=((('fc' in h or 'flow' in h) and ('cm' in h or 'conditioned' in h)) and 'ctg' not in h and 'bulk' not in h)
        if not fc_cm: continue
